<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/functions.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT r.*,c.name category,u.full_name reporter FROM item_reports r JOIN categories c ON c.id=r.category_id JOIN users u ON u.id=r.user_id WHERE r.id=?");$s->execute([$id]);$item=$s->fetch();if(!$item){http_response_code(404);$pageTitle='Item not found';require __DIR__.'/../includes/header.php';echo '<div class="empty">Item not found.</div>';require __DIR__.'/../includes/footer.php';exit;}$pageTitle='Item details';require __DIR__.'/../includes/header.php';?><article class="detail panel"><span class="pill <?=e($item['report_type'])?>"><?=e(ucfirst($item['report_type']))?></span><h1><?=e($item['item_name'])?></h1><p><?=e($item['category'])?> · <?=e($item['location'])?></p><p><b>Date:</b> <?=e($item['date_occurred'])?></p><p><?=nl2br(e($item['description']))?></p><p class="muted">Status: <?=e($item['status'])?></p><?php if(current_user()&&current_user()['role']==='student'&&(int)$item['user_id']!==(int)current_user()['id']&&$item['report_type']==='found'&&$item['status']==='open'):?><a class="btn primary" href="<?=e(url('student/submit-claim.php?item_id='.(int)$item['id']))?>">Claim this item</a><?php endif;?></article><?php require __DIR__.'/../includes/footer.php';?>
